export type OrgFieldType =
  | "text"
  | "textarea"
  | "date"
  | "number"
  | "currency"
  | "percent"
  | "email"
  | "tel"
  | "url"
  | "select"
  | "list"
  | "multiselect"
  | "checkbox"
  | "file"
  | "readonly"
  | "studio-permissions"
  | "product-participation"
  | "assigned-products"
  | "audit-history";

export type OrgFieldOption = { value: string; label: string };

export type OrgOptionSource = "product-families";

export type OrgFieldBind =
  | "name"
  | "code"
  | "legalName"
  | "status"
  | "type"
  | "notes"
  | "parentCompanyName"
  | "parentCompanyName"
  | "contactName"
  | "contactEmail"
  | "contactPhone"
  | "address"
  | "createdBy"
  | "createdDate"
  | "lastModifiedBy"
  | "lastModifiedDate";

export type OrgField = {
  key: string;
  label: string;
  type: OrgFieldType;
  required?: boolean;
  placeholder?: string;
  help?: string;
  options?: OrgFieldOption[];
  optionsSource?: OrgOptionSource;
  bind?: OrgFieldBind;
  wide?: boolean;
};

export type OrgSection = {
  key: string;
  title: string;
  hint?: string;
  intro?: string;
  fields: OrgField[];
};

export type OrgTypeFieldConfig = {
  sections: OrgSection[];
};

const opt = (value: string, label?: string): OrgFieldOption => ({ value, label: label || value });

